/**
 * Returns fully localized prediction objects for a given Lagna & selected language
 */
export function getLocalizedPredictionsData(kundali, lang = 'hi') {
  const selectedLang = ['en', 'hi', 'kn', 'mr', 'te'].includes(lang) ? lang : 'hi';
  const lagnaRashi = kundali.lagna.rashiName;
  const lagnaLord = kundali.lagna.lord;
  const house2 = kundali.houses[1];
  const house7 = kundali.houses[6];
  const house10 = kundali.houses[9];
  const house11 = kundali.houses[10];

  const jupiter = kundali.planets.find(p => p.name === 'Jupiter') || { house: 1 };
  const mercury = kundali.planets.find(p => p.name === 'Mercury') || { house: 1 };

  // Health
  const rashiHealth = HEALTH_CONSTITUTIONS_MULTILINGUAL[lagnaRashi] || HEALTH_CONSTITUTIONS_MULTILINGUAL.Aries;
  const healthData = rashiHealth[selectedLang] || rashiHealth.hi;

  // Dhana Yogas
  const L = PREDICTION_TEXT[selectedLang] || PREDICTION_TEXT.hi;
  const dhanaYogas = [];
  if (['Sun', 'Jupiter', 'Venus'].includes(house2.lord) || ['Sun', 'Jupiter', 'Venus'].includes(house11.lord)) {
    dhanaYogas.push(L.dhanaYogas.mahadhana);
  }
  if (jupiter.house === 1 || jupiter.house === 4 || jupiter.house === 7 || jupiter.house === 10) {
    dhanaYogas.push(L.dhanaYogas.hamsa);
  }
  if (mercury.house === 1 || mercury.house === 5 || mercury.house === 10) {
    dhanaYogas.push(L.dhanaYogas.bhadra);
  }
  if (dhanaYogas.length === 0) {
    dhanaYogas.push(L.dhanaYogas.vasumathi);
  }

  const isBusiness = ['Mercury', 'Venus', 'Mars'].includes(house10.lord) || ['Mercury', 'Venus'].includes(lagnaLord);
  const isMarriageYoung = ['Jupiter', 'Venus'].includes(house7.lord);

  const currentYear = new Date().getFullYear();
  const Q = QUARTERLY_FORECAST_TEXT[selectedLang] || QUARTERLY_FORECAST_TEXT.hi;

  return {
    health: {
      constitution: healthData.dosha,
      vulnerableOrgans: healthData.organs,
      ayurvedicAdvice: healthData.advice,
      longevityFactor: L.longevityFactor
    },
    wealth: {
      dhanaYogas: dhanaYogas,
      primeAssetClasses: L.wealthAnchor,
      financialTiming: L.financialTiming
    },
    career: {
      style: isBusiness ? L.careerBusiness : L.careerService,
      leadershipTrait: L.leadershipTrait
    },
    marriage: {
      ageWindow: isMarriageYoung ? L.marriageYoung.split(' • ')[0] : L.marriageMature.split(' • ')[0],
      spouseNature: isMarriageYoung ? L.marriageYoung.split(' • ')[1] : L.marriageMature.split(' • ')[1]
    },
    spirituality: {
      sadhana: L.sadhana
    },
    quarterlyForecast: {
      year: currentYear,
      q1: Q.q1,
      q2: Q.q2,
      q3: Q.q3,
      q4: Q.q4
    },
    remedies: {
      consecrationSteps: L.consecrationSteps,
      forbiddenGems: L.forbiddenGems,
      daanSeva: L.daanSeva,
      shaniDeepam: L.shaniDeepam
    }
  };
}

