export function getLocalizedJanamNaam(nakshatraIndex, pada, lang = 'hi') {
  const pIndex = Math.max(0, Math.min(3, (pada || 1) - 1));
  const nakEntry = NAKSHATRA_SYLLABLES_NATIVE[nakshatraIndex] || NAKSHATRA_SYLLABLES_NATIVE[1];
  const langKey = ['en', 'hi', 'kn', 'mr', 'te'].includes(lang) ? lang : 'hi';
  const syllable = nakEntry[langKey]?.[pIndex] || nakEntry.hi[pIndex] || 'मा';

  const explanations = {
    kn: `ಚಂದ್ರನ ನಕ್ಷತ್ರ ಮತ್ತು ${pada}ನೇ ಪಾದದ ಆಧಾರದ ಮೇಲೆ, ಶಾಸ್ತ್ರೋಕ್ತ ನಾಮಕರಣಕ್ಕೆ ಅತ್ಯಂತ ಮಂಗಳಕರವಾದ ಮೊದಲ ಅಕ್ಷರ "${syllable}".`,
    hi: `चन्द्रमा के नक्षत्र एवं ${pada}वें चरण के आधार पर, शास्त्रोक्त नामकरण हेतु परम शुभ आद्य अक्षर "${syllable}"।`,
    mr: `चंद्राच्या नक्षत्र व ${pada}व्या चरणानुसार नामकरणासाठी अत्यंत शुभ आद्याक्षर "${syllable}".`,
    te: `చంద్రుని నక్షత్రం మరియు ${pada}వ పాదం ఆధారంగా నామకరణానికి పరమ పవిత్రమైన ప్రథమాక్షరం "${syllable}".`,
    en: `Based on Moon's placement in Pada ${pada}, the sacred initial phonetic vibration for naming is "${syllable}".`
  };

  return {
    syllable,
    explanation: explanations[langKey] || explanations.hi
  };
}

// Classical Parashari Dignity Rule Calculator (Eliminates undefined 100%)
export function getPlanetDignityKey(planetName, rashi) {
  switch (planetName) {
    case 'Sun':
      if (rashi === 1) return 'Exalted';       // Aries
      if (rashi === 7) return 'Debilitated';   // Libra
      if (rashi === 5) return 'Own';           // Leo
      if ([4, 8, 9, 12].includes(rashi)) return 'Friend'; // Cancer, Scorpio, Sag, Pisces
      if ([2, 10, 11].includes(rashi)) return 'Enemy';    // Taurus, Cap, Aqua
      return 'Neutral'; // Gemini, Virgo
    case 'Moon':
      if (rashi === 2) return 'Exalted';       // Taurus
      if (rashi === 8) return 'Debilitated';   // Scorpio
      if (rashi === 4) return 'Own';           // Cancer
      if ([5, 3, 6].includes(rashi)) return 'Friend'; // Leo, Gemini, Virgo
      return 'Neutral';
    case 'Mars':
      if (rashi === 10) return 'Exalted';      // Capricorn
      if (rashi === 4) return 'Debilitated';   // Cancer
      if ([1, 8].includes(rashi)) return 'Own';// Aries, Scorpio
      if ([5, 9, 12].includes(rashi)) return 'Friend'; // Leo, Sag, Pisces
      if ([3, 6].includes(rashi)) return 'Enemy';      // Gemini, Virgo
      return 'Neutral';
    case 'Mercury':
      if (rashi === 6) return 'Exalted';       // Virgo
      if (rashi === 12) return 'Debilitated';  // Pisces
      if (rashi === 3) return 'Own';           // Gemini
      if ([5, 2, 7].includes(rashi)) return 'Friend'; // Leo, Taurus, Libra
      if (rashi === 4) return 'Enemy';         // Cancer
      return 'Neutral';
    case 'Jupiter':
      if (rashi === 4) return 'Exalted';       // Cancer
      if (rashi === 10) return 'Debilitated';  // Capricorn
      if ([9, 12].includes(rashi)) return 'Own'; // Sag, Pisces
      if ([1, 5, 8].includes(rashi)) return 'Friend'; // Aries, Leo, Scorpio
      if ([3, 6, 2, 7].includes(rashi)) return 'Enemy'; // Gemini, Virgo, Taurus, Libra
      return 'Neutral';
    case 'Venus':
      if (rashi === 12) return 'Exalted';      // Pisces
      if (rashi === 6) return 'Debilitated';   // Virgo
      if ([2, 7].includes(rashi)) return 'Own'; // Taurus, Libra
      if ([3, 10, 11].includes(rashi)) return 'Friend'; // Gemini, Cap, Aqua
      if ([5, 4].includes(rashi)) return 'Enemy';       // Leo, Cancer
      return 'Neutral';
    case 'Saturn':
      if (rashi === 7) return 'Exalted';       // Libra
      if (rashi === 1) return 'Debilitated';   // Aries
      if ([10, 11].includes(rashi)) return 'Own'; // Cap, Aqua
      if ([2, 3, 6].includes(rashi)) return 'Friend'; // Taurus, Gemini, Virgo
      if ([4, 5, 8].includes(rashi)) return 'Enemy';  // Cancer, Leo, Scorpio
      return 'Neutral';
    case 'Rahu':
      if (rashi === 2) return 'Exalted';       // Taurus
      if (rashi === 8) return 'Debilitated';   // Scorpio
      if ([3, 6, 7, 11].includes(rashi)) return 'Friend';
      if ([1, 4, 5].includes(rashi)) return 'Enemy';
      return 'Neutral';
    case 'Ketu':
      if (rashi === 8) return 'Exalted';       // Scorpio
      if (rashi === 2) return 'Debilitated';   // Taurus
      if ([9, 12].includes(rashi)) return 'Friend';
      if ([4, 5].includes(rashi)) return 'Enemy';
      return 'Neutral';
    default:
      return 'Neutral';
  }
}

