// Replaces getLocalizedAttributes to provide 100% pure native attributes
export function getPureLocalizedAttributes(attrs, lang = 'hi', lagnaSign = 'Sagittarius') {
  const langKey = ['en', 'hi', 'kn', 'mr', 'te'].includes(lang) ? lang : 'hi';
  const rashiAttrs = RASHIS_ATTRIBUTES_LOCALIZED[lagnaSign]?.[langKey] || RASHIS_ATTRIBUTES_LOCALIZED.Sagittarius[langKey];

  return {
    ...attrs,
    luckyColors: rashiAttrs.luckyColors,
    unluckyColors: rashiAttrs.unluckyColors,
    favorableDirections: rashiAttrs.favorableDirections,
    unfavorableDirections: rashiAttrs.unfavorableDirections,
    favorableDays: rashiAttrs.favorableDays,
    unfavorableDays: rashiAttrs.unfavorableDays,
    lifeGem: rashiAttrs.lifeGem,
    avoidGem: rashiAttrs.avoidGem,
    rudraksha: rashiAttrs.rudraksha
  };
}



