export function getLocalizedDebtTitle(title, lang = 'hi') {
  const lower = (title || '').toLowerCase();
  if (lower.includes('matru') || lower.includes('मातृ') || lower.includes('maternal')) {
    return { kn: 'ಮಾತೃ ಋಣ (ಶಾಂತಿ ಪರಿಹಾರ ಸೂಕ್ತ)', hi: 'मातृ ऋण (शांति उपाय विहित)', mr: 'मातृ ऋण (शांती उपाय विहित)', te: 'మాతృ రుణం (శాంతి పరిహారం అనుకూలం)', en: 'Maternal Karmic Debt' }[lang] || 'Matru Rin';
  }
  if (lower.includes('pitru') || lower.includes('पितृ') || lower.includes('father') || lower.includes('ancestral')) {
    return { kn: 'ಪಿತೃ ಋಣ (ಪೂರ್ವಜರ ತರ್ಪಣ ಸೂಕ್ತ)', hi: 'पितृ ऋण (पितृ तर्पण विहित)', mr: 'पितृ ऋण (पितृ तर्पण विहित)', te: 'పితృ రుణం (తర్పణం అనుకూలం)', en: 'Ancestral Debt' }[lang] || 'Pitru Rin';
  }
  if (lower.includes('bhratri') || lower.includes('भ्रातृ') || lower.includes('brother') || lower.includes('sibling')) {
    return { kn: 'ಭ್ರಾತೃ ಋಣ (ಸಹೋದರ ಪ್ರೇಮ ಸೂಕ್ತ)', hi: 'भ्रातृ ऋण (सहोदर प्रेम विहित)', mr: 'भ्रातृ ऋण (बंधुप्रेम विहित)', te: 'భ్రాతృ రుణం', en: 'Sibling Debt' }[lang] || 'Bhratri Rin';
  }
  if (lower.includes('guru') || lower.includes('गुरु') || lower.includes('preceptor')) {
    return { kn: 'ಗುರು ಋಣ (ಗುರು ಸೇವೆ ಸೂಕ್ತ)', hi: 'गुरु ऋण (गुरु सेवा विहित)', mr: 'गुरु ऋण (गुरु सेवा विहित)', te: 'గురు రుణం', en: 'Preceptor Debt' }[lang] || 'Guru Rin';
  }
  if (lower.includes('deva') || lower.includes('देव') || lower.includes('divine')) {
    return { kn: 'ದೈವ ಋಣ (ಇಷ್ಟದೇವತಾ ಆರಾಧನೆ)', hi: 'देव ऋण (इष्टदेव पूजन विहित)', mr: 'देव ऋण (इष्टदेवता पूजा)', te: 'దేవ రుణం', en: 'Divine Debt' }[lang] || 'Deva Rin';
  }
  return title;
}

export function getRashiName(rashi, lang = 'hi') {
  if (!rashi) return '';
  const rashiNameToNum = {
    Aries: 1, Taurus: 2, Gemini: 3, Cancer: 4, Leo: 5, Virgo: 6,
    Libra: 7, Scorpio: 8, Sagittarius: 9, Capricorn: 10, Aquarius: 11, Pisces: 12
  };
  const num = typeof rashi === 'number' ? rashi : (rashiNameToNum[rashi] || parseInt(rashi, 10));
  if (num && LOCALIZED_RASHIS[num]) {
    return LOCALIZED_RASHIS[num][lang] || LOCALIZED_RASHIS[num].en || rashi;
  }
  return rashi;
}
